// Generated by build/build.mjs. Pages are network-first so updates to the handbook show as soon as
// there is signal; everything is cached so the handbook still opens with no signal.
const CACHE = '__CACHE__';
const PRECACHE = __PRECACHE__;
const PDF = '__PDF__';

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(PRECACHE.map((u) => new Request(u, { cache: 'reload' })))).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith('haloqrh-') && k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  const isPage = req.mode === 'navigate' || req.url.endsWith('.html');
  const isPdf = req.url.endsWith(PDF);
  if (isPage || isPdf) {
    e.respondWith(fetch(req).then((res) => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
      return res;
    }).catch(() => caches.match(req, { ignoreSearch: true }).then((r) => r || caches.match(isPage ? './' : req))));
    return;
  }
  e.respondWith(caches.match(req).then((r) => r || fetch(req)));
});
